export async function charge(payload, { send, makeKey }) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const key = makeKey();
    const response = await send({ payload, idempotencyKey: key });
    if (response.status === 429 && attempt < 2) continue;
    return response;
  }
}
